// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: attacker EOA that will deploy/trigger a relay contract, and the candidate newOwner
    function testFuzz_property(address attacker, address candidateNewOwner) public {
        // Keep addresses non-zero to be meaningful but otherwise wide
        vm.assume(attacker != address(0));
        vm.assume(candidateNewOwner != address(0));
        // The property: in the correct contract, only the current owner (an EOA that deployed c) can call setOwner.
        // We will simulate a scenario where an EOA (attacker) deploys a Relay which then calls c.setOwner.
        // Under the correct contract (which checks msg.sender), the Relay's call will have msg.sender == Relay,
        // so it should fail unless Relay == owner. Since owner was set in setUp() to the test contract deployer (this address),
        // Relay != owner and the call must NOT succeed for any attacker/candidateNewOwner.
        // Under the mutant (which checks tx.origin), the Relay's call would see tx.origin == attacker,
        // and if attacker==owner the Relay could succeed; but since owner is the deployer of c (test contract address),
        // there exist attacker values (specifically attacker == address(this) or others via prank) that make behavior differ.

        // Deploy a Relay contract from the fuzzed attacker EOA, so tx.origin will be attacker when Relay calls c.
        vm.prank(attacker);
        Relay r = new Relay();

        // Ensure the Relay's call is performed: have Relay attempt to call c.setOwner(candidateNewOwner).
        // We call via the relay so that msg.sender inside C will be Relay, and tx.origin will be attacker.
        bool ok;
        try r.callSetOwner(address(c), candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property that must hold for the reference implementation:
        // After any call to setOwner that originated from an EOA deploying a relay (so msg.sender != tx.origin),
        // the call must NOT succeed because msg.sender != owner (owner was set in setUp() to the test-deployer address).
        // Therefore, for all attacker and candidateNewOwner, the call via Relay must fail (ok == false) on the correct contract.
        // The mutant that uses tx.origin may let the call succeed for some attacker values, breaking this assertion.

        assertTrue(ok == false);
    }
}

// Minimal adversarial relay contract that simply tries to call C.setOwner
contract Relay {
    function callSetOwner(address cAddr, address newOwner) external {
        C(cAddr).setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker (an EOA) and candidateNewOwner (an address)
    // We will deploy a Relay contract that calls c.setOwner on behalf of the attacker.
    // General rule: only the current owner (as msg.sender) can change owner. The mutant uses tx.origin and thus
    // allows a relayer contract to bypass the msg.sender check. We fuzz attacker and candidateNewOwner.
    function testFuzz_property(address attacker, address candidateNewOwner) public {
        // Keep domain wide but avoid trivial zero-address for candidate to ensure meaningful ownership change
        // (still wide: allow zero but prefer non-zero by bounding to non-extreme values)
        candidateNewOwner = bound(candidateNewOwner, address(1), address(type(uint160).max));
        attacker = bound(attacker, address(1), address(type(uint160).max));

        // Ensure attacker is not the current owner (so direct call should fail under correct contract)
        address originalOwner = c.owner();
        vm.assume(attacker != originalOwner);

        // Deploy a Relay contract whose msg.sender will be the Relay contract when it calls c.setOwner;
        // tx.origin will be attacker. This exercises the difference between msg.sender vs tx.origin.
        Relay relay = new Relay(c);

        // Fund attacker so they can send txs (prank uses EOA addresses)
        vm.deal(attacker, 1 ether);

        // Make the attacker be the tx.origin for the call from Relay by starting a prank as attacker
        vm.startPrank(attacker);
        // Call Relay to instruct it to call c.setOwner(candidateNewOwner). From c's perspective:
        // - msg.sender == address(relay)
        // - tx.origin == attacker
        relay.relaySetOwner(candidateNewOwner);
        vm.stopPrank();

        // Now check: in the correct contract, since msg.sender (relay) != originalOwner, the setOwner should NOT have succeeded.
        // So owner must still equal originalOwner. In the mutant (tx.origin check), tx.origin == attacker could be incorrectly
        // considered owner if attacker == originalOwner; but we assumed attacker != originalOwner, so mutant would still fail
        // unless it treats tx.origin == owner — to trigger mutant we need attacker == originalOwner. Therefore instead we
        // craft the adversarial scenario so the tx.origin is the originalOwner: let owner (EOA) cause a relayed transaction
        // where msg.sender != owner but tx.origin == owner. To do that we need owner to be the EOA originator. We will redo with that.

        // Re-deploy clean instance and redo with originator == originalOwner to expose mutant.
        // Create fresh contract instance to reset state and ensure deterministic outcome.
        c = new C();
        originalOwner = c.owner();
        // Ensure originalOwner is an EOA we can prank as: Foundry's default deployer is an EOA and is owner.
        // Deploy a new Relay and have originalOwner (tx.origin) call into it, which then calls c.setOwner with msg.sender == relay
        Relay relay2 = new Relay(c);

        // Ensure candidateNewOwner is not equal to originalOwner to observe change only under mutant
        vm.assume(candidateNewOwner != originalOwner);

        // Start prank as originalOwner so tx.origin == originalOwner
        vm.startPrank(originalOwner);
        // Relay will call c.setOwner(candidateNewOwner) with msg.sender == address(relay2), tx.origin == originalOwner
        relay2.relaySetOwner(candidateNewOwner);
        vm.stopPrank();

        // Assertion: In the correct contract, only direct calls where msg.sender == owner can change owner.
        // Because this call was relayed (msg.sender == relay2 != originalOwner), the owner MUST remain originalOwner.
        // The mutant which checks tx.origin == owner will allow this relayed call to succeed, making owner == candidateNewOwner.
        assertTrue(c.owner() == originalOwner);
    }
}

// Minimal relay contract that forwards a setOwner call to C
contract Relay {
    C immutable target;
    constructor(C _target) { target = _target; }
    function relaySetOwner(address newOwner) external {
        // call target.setOwner from this contract (msg.sender == address(this), tx.origin == original caller)
        target.setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an EOA that will be the original owner (ownerAddr) and a different EOA attacker
    // The fuzzer will pick addresses; we will bound them to non-zero and ensure they differ.
    function testFuzz_property(address ownerAddr, address attackerEOA) public {
        // keep inputs admissible and wide
        vm.assume(ownerAddr != address(0));
        vm.assume(attackerEOA != address(0));
        vm.assume(ownerAddr != attackerEOA);

        // Fund both EOAs so they can send transactions
        vm.deal(ownerAddr, 1 ether);
        vm.deal(attackerEOA, 1 ether);

        // Make ownerAddr the contract owner by having it deploy a fresh C and then transferring ownership
        // but spec requires c is deployed in setUp() by this test runner; current owner is address(this) deployer
        // So first, transfer ownership from deployer (address(this)) to ownerAddr by calling setOwner as the deployer
        // The deployer is the current owner, so this call should succeed on the reference contract
        bool ok;
        try c.setOwner(ownerAddr) { ok = true; } catch { ok = false; }
        // ensure the initial transfer to ownerAddr succeeded (both reference and mutant allow deployer to change owner)
        assertTrue(ok);
        assertTrue(c.owner() == ownerAddr);

        // Deploy a relayer contract that, when called by attackerEOA, will call c.setOwner(attackerEOA) from the relayer
        Relayer relayer = new Relayer(c);

        // attackerEOA calls the relayer which in turn calls c.setOwner(attackerEOA)
        // For the reference contract (uses msg.sender), this should revert/fail because relayer != ownerAddr
        // For the mutant (uses tx.origin), tx.origin == attackerEOA and if ownerAddr == attackerEOA it would succeed,
        // but we ensured ownerAddr != attackerEOA, so mutant will incorrectly allow the relayer to change owner because tx.origin is attackerEOA

        vm.prank(attackerEOA);
        // call relayer which forwards to c
        relayer.relaySetOwner(attackerEOA);

        // Exactly one assertion: in the correct contract, after the relayed call, owner remains ownerAddr
        assertTrue(c.owner() == ownerAddr);
    }
}

// minimal relayer that calls c.setOwner on behalf of msg.sender
contract Relayer {
    C public c;
    constructor(C _c) { c = _c; }
    function relaySetOwner(address newOwner) external {
        // forward call to c; msg.sender here will be this contract
        c.setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: the relayer contract's initial owner (as an address to become the relayer's controller)
    // and the desired newOwner to pass into c.setOwner when relayed.
    // We fuzz two addresses: relayerController (who will be the EOA that deploys/controls the relayer)
    // and targetNewOwner (the address passed to setOwner through the relayer).
    function testFuzz_property(address relayerController, address targetNewOwner) public {
        // keep addresses wide but non-zero to avoid trivial zero-address edgecases
        vm.assume(relayerController != address(0));
        vm.assume(targetNewOwner != address(0));
        // Deploy a relayer contract from relayerController so that tx.origin == relayerController
        vm.prank(relayerController);
        Relayer r = new Relayer();

        // At deployment, c.owner() == address(this test contract deployer) from setUp();
        address initialOwner = c.owner();

        // If the owner (EOA) directly calls setOwner, reference allows it only when msg.sender == owner.
        // Ensure relayerController is NOT the initial owner so direct calls from relayerController would fail on reference.
        vm.assume(relayerController != initialOwner);

        // Now, have the relayer contract invoke c.setOwner(targetNewOwner) using a low-level call
        // This makes msg.sender == address(r) and tx.origin == relayerController
        bool ok;
        try r.relaySetOwner{value:0}(address(c), targetNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property (single assertion): On the correct contract C, a relayed call where msg.sender != owner MUST NOT succeed in changing owner.
        // We observe this by asserting that c.owner() is either unchanged (if the relayed call reverted) or, if it succeeded,
        // then the caller that succeeded must have been msg.sender == owner — but since msg.sender == address(r) and we ensured relayerController != initialOwner,
        // the correct contract will not allow the relayed change. Thus for all admissible inputs the owner remains initialOwner.
        assertTrue(c.owner() == initialOwner);
    }
}

// Minimal relayer: simply calls setOwner on target contract using its own address as msg.sender.
contract Relayer {
    function relaySetOwner(address target, address newOwner) external {
        // call setOwner on target
        // forward all gas and don't expect return data; if it reverts, this call will revert
        (bool s, ) = target.call(abi.encodeWithSignature("setOwner(address)", newOwner));
        require(s);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: relayerAddr is any address used to deploy the relayer contract (fuzzer chooses)
    // newOwner is the target owner we ask setOwner to set
    function testFuzz_property(address relayerAddr, address newOwner) public {
        // Keep addresses non-zero to be meaningful
        vm.assume(relayerAddr != address(0));
        vm.assume(newOwner != address(0));

        // The contract C sets owner = msg.sender in constructor; so test deployer (address(this)) is owner
        address initialOwner = c.owner();
        // Ensure initial owner is this test contract (setUp used new C(), owner set to msg.sender == address(this))
        // This should always hold for the reference contract
        vm.assume(initialOwner == address(this));

        // Deploy a relayer contract from the fuzzed relayerAddr to simulate a contract that will call c.setOwner
        // Use vm.prank to make the deployer be relayerAddr so the relayer contract's creator is relayerAddr
        vm.startPrank(relayerAddr);
        Relayer r = new Relayer();
        vm.stopPrank();

        // Now have the relayer call c.setOwner(newOwner).
        // Important: when relayer performs the external call, within c: msg.sender == address(r), tx.origin == relayerAddr
        // For the reference contract, only msg.sender == current owner (address(this)) can succeed, so the relayer call should NOT change owner.
        bool ok;
        try r.relaySetOwner(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: in the correct contract, the relayer (a contract) cannot change owner because msg.sender != owner;
        // therefore after the relayed call the owner must remain the original owner (address(this)).
        // The mutant that checks tx.origin instead can allow the change when tx.origin == relayerAddr equals the original owner
        // (but we ensured original owner == address(this), so the mutant will only succeed if tx.origin == address(this)); the fuzzer
        // can pick relayerAddr == address(this) to trigger the mutant, so the single assertion distinguishes them.
        assertTrue(c.owner() == address(this));
    }
}

// Minimal relayer contract that simply calls setOwner on C
contract Relayer {
    function relaySetOwner(address caddr, address newOwner) public {
        C(caddr).setOwner(newOwner);
    }
}
